# server.js
// server.js — API tối giản: trả thời gian từ Postgres nếu kết nối được.
// Thư viện pg tự đọc PGHOST / PGUSER / PGPASSWORD / PGDATABASE từ biến môi trường.
const http = require('http');
const { Client } = require('pg');

http.createServer(async (_req, res) => {
  const host = process.env.PGHOST || 'localhost';
  const client = new Client({ connectionTimeoutMillis: 1500 });
  res.setHeader('Content-Type', 'application/json');
  try {
    await client.connect();
    const r = await client.query('SELECT NOW() AS now');
    await client.end();
    res.end(JSON.stringify({ status: 'ok', db_host: host, db_time: r.rows[0].now }));
  } catch (e) {
    res.end(JSON.stringify({ status: 'app-up', db_host: host, db: 'unreachable' }));
  }
}).listen(3000, () => console.log('app listening on :3000'));

# package.json
{
  "name": "docker-demo-app",
  "version": "1.0.0",
  "main": "server.js",
  "dependencies": { "pg": "^8.13.0" }
}

